001\u4fdd\u6e29\u3001\u8bd5\u9a8c\u7b49\u65b9\u5f0f\u63a7\u5236\u6df7\u51dd\u571f\u53ca\u6d47\u7b51\u8d28\u91cf\u3002\u4e3a\u4fdd\u8bc1\u5927\u4f53\u79ef\u6df7\u51dd\u571f\u7684\u6574\u4f53\u6027\uff0c\u5de5\u7a0b\u91c7\u7528\u73af\u6c27\u6811\u8102\u704c\u6ce8\u7684\u65b9\u5f0f\u6765\u5904\u7406\u5206\u4ed3\u7f1d\u3002\u65bd\u5de5\u65b9\u7ecf\u8fc7\u591a\u6b21\u8bd5\u9a8c\uff0c\u7814\u7a76\u704c\u6ce8\u65bd\u5de5\u65b9\u6cd5\u5e76\u6bd4\u5bf9\u65bd\u5de5\u6548\u679c\uff0c\u4e14\u901a\u8fc7\u8bd5\u9a8c\u6bb5\u7684\u526a\u5207\u6ce2\u901f\u68c0\u6d4b\uff0c\u704c\u6ce8\u5904\u7406\u540e\u7684\u6df7\u51dd\u571f\u57fa\u7840\u6ee1\u8db3\u8bbe\u8ba1\u8981\u6c42\uff0c\u4e3a\u5fae\u632f\u52a8\u63a7\u5236\u63d0\u4f9b\u4e86\u66f4\u597d\u4fdd\u969c\u3002\u76ee\u524d\u65bd\u5de5\u65b9\u5df2\u7ecf\u638c\u63e1\u4e86\u5b8c\u5584\u7684\u704c\u6ce8\u65bd\u5de5\u6280\u672f\uff0c\u6b63\u5728\u5927\u9762\u79ef\u5f00\u5c55\u5206\u4ed3\u7f1d\u5904\u7406\u5de5\u4f5c\u3002\n\u9664\u9632\u5fae\u632f\u57fa\u7840\u65bd\u5de5\u4e4b\u5916\uff0c\u5404\u9879\u5efa\u8bbe\u5de5\u4f5c\u5747\u53d6\u5f97\u4e0d\u540c\u7a0b\u5ea6\u8fdb\u5c55\uff1a\u5176\u4e2d\u589e\u5f3a\u5668\u9ad8\u9891\u5385\u3001\u4e8c\u53f7\u7efc\u5408\u52a8\u529b\u7ad9\u3001\u4e09\u53f7\u6280\u672f\u5b89\u5168\u697c\u6b63\u5728\u8fdb\u884c\u4e3b\u4f53\u7ed3\u6784\u65bd\u5de5\uff0c\u9884\u8ba1\u56db\u6708\u4e0b\u65ec\u53ef\u9646\u7eed\u5c01\u9876\u5e76\u5f00\u59cb\u8fdb\u884c\u4e8c\u6b21\u7ed3\u6784\u65bd\u5de5\uff1b\u50a8\u5b58\u73af\u5916\u5708\u5b9e\u9a8c\u5385\u6b63\u5728\u8fdb\u884c\u4e3b\u4f53\u7ed3\u6784\u65bd\u5de5\uff0c\u90e8\u5206\u533a\u57df\u6b63\u5728\u8fdb\u884c\u9876\u677f\u65bd\u5de5\uff1b\u51c6\u76f4\u6869\u7684\u6df1\u6869\u94a2\u5957\u7b52\u5df2\u5168\u90e8\u62fc\u88c5\u5b8c\u6210\uff0c\u5e76\u5df2\u5b8c\u62103\u6839\u94a2\u5957\u7b52\u7684\u540a\u88c5\uff1b\u4eba\u9632\u5de5\u7a0b\u5df2\u5b8c\u6210363\u4e2a\u4eba\u5de5\u6316\u5b54\u62a4\u5761\u6869\u65bd\u5de5\u53ca\u51a0\u6881\u6d47\u7b51\uff0c\u6b63\u5728\u8fdb\u884c\u571f\u65b9\u5f00\u6316\u3002\n\u9879\u76ee\u73b0\u573a\u5404\u9879\u5efa\u8bbe\u5de5\u4f5c\u6b63\u5728\u5982\u706b\u5982\u837c\u7684\u8fdb\u884c\uff0c\u5728\u75ab\u60c5\u9632\u63a7\u7684\u7279\u6b8a\u65f6\u671f\uff0c\u5404\u53c2\u5efa\u5355\u4f4d\u4e00\u624b\u6293\u9632\u75ab\u4e00\u624b\u6293\u751f\u4ea7\u3002\u9632\u5fae\u632f\u6362\u586b\u57fa\u7840\u662fHEPS\u9879\u76ee\u7684\u91cd\u8981\u5173\u952e\u6280\u672f\uff0c\u57fa\u7840\u65bd\u5de5\u7684\u5b8c\u6210\uff0c\u6807\u5fd7\u7740HEPS\u9879\u76ee\u7684\u57fa\u5efa\u5efa\u8bbe\u5df2\u7ecf\u653b\u514b\u7b2c\u4e00\u4e2a\u96be\u5173\u3002\u672a\u6765\uff0c\u5404\u53c2\u5efa\u5355\u4f4d\u5c06\u7ee7\u7eed\u52aa\u529b\uff0c\u9ad8\u8d28\u91cf\u5efa\u8bbe\u597d\u56fd\u5bb6\u91cd\u5927\u79d1\u6280\u57fa\u7840\u8bbe\u65bdHEPS\u9879\u76ee\u3002\n\u822a\u62cd\u5168\u666f\n\u6362\u586b\u5730\u57fa\uff08\u7b2c\u4e09\u5c420.8\u7c73\uff09\u6d47\u7b51\u5b8c\u6210\n\u4eba\u9632\u5de5\u7a0b363\u4e2a\u4eba\u5de5\u6316\u5b54\u6869\u51a0\u6881\n\u51c6\u76f4\u6869\u94a2\u5957\u7b52",
